//! ↩️ Native optional text inverses preserve original owners and measured cancellation.
use super::*;
use semio_framework_value::retained_clone::RetainedCloneBorrowAuthority;
fn grant(turn:usize)->RetainedCloneGrant{match turn%3{0=>RetainedCloneGrant::one_capacity_turn(4096,128),1=>RetainedCloneGrant::one_payload_turn(4096,128),_=>RetainedCloneGrant::one_release_turn(4096,128)}}
fn observed(step:Result<RetainedCloneStep,ValueError>,heap:semio_framework_trace::HeapAllocationObservation,grant:RetainedCloneGrant)->RetainedCloneStep{
 let step=step.unwrap();let progress=step.progress();assert!(progress.fits(grant));assert!(!heap.overflowed);assert!(heap.requested_bytes<=progress.retained_capacity_bytes);assert!(heap.released_bytes<=progress.released_bytes);assert!(progress.copied_bytes+progress.retained_capacity_bytes+progress.released_bytes<=4096);step
}
fn close<T:Puzzle2dTextInverse>(cursor:&mut Puzzle2dTextInverseCursor<T>){cursor.begin_close();for turn in 0..100000{if cursor.terminal_is_empty(){return}let g=grant(turn);let(step,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||cursor.close_step(g));observed(step,heap,g);}panic!("optional text inverse did not retire")}
fn law<T:Puzzle2dTextInverse+Clone>(snapshot:&Puzzle2dSnapshot,payload:T,expected:&serde_json::Value){
 let original=serde_json::to_value(snapshot).unwrap();let source=RetainedCloneBorrowAuthority::new("original text inverse snapshot");let mutation=RetainedCloneBorrowAuthority::new("original text inverse intent");
 let(mut cursor,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(Puzzle2dTextInverseCursor::<T>::default);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));
 let(step,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||cursor.advance(source.borrow(snapshot),mutation.borrow(&payload),RetainedCloneGrant::default()));assert_eq!(step.unwrap(),RetainedCloneStep::Progress(Default::default()));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));
 let mut complete=false;for turn in 0..100000{let g=grant(turn);let(step,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||cursor.advance(source.borrow(snapshot),mutation.borrow(&payload),g));if matches!(observed(step,heap,g),RetainedCloneStep::Complete(_)){complete=true;break}}
 assert!(complete,"optional text inverse did not complete");let inverse=cursor.take().unwrap();assert_eq!(inverse.len(),expected.as_array().unwrap().len());
 if let Some(operation)=inverse.first(){let(id,previous)=match operation{Puzzle2dMutation::ChangeNodeIcon(value)=>(&value.id,&value.new_icon_kind),Puzzle2dMutation::EditTargetRegionLabel(value)=>(&value.id,&value.new_label),_=>panic!("wrong optional setter")};assert_eq!(serde_json::to_value(id).unwrap(),expected[0]["id"]);assert_eq!(serde_json::to_value(previous).unwrap(),expected[0]["previous"])}
 close(&mut cursor);let mut owner=ControlledRetirement::new(inverse).map_err(|(error,_)|error).unwrap();for turn in 0..100000{if owner.terminal_is_empty(){break}let g=grant(turn);let(step,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.step(g));observed(step,heap,g);}assert!(owner.terminal_is_empty());
 for pause in [0,1,3,7,17]{let mut cursor=Puzzle2dTextInverseCursor::<T>::default();for turn in 0..pause{let g=grant(turn);let(step,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||cursor.advance(source.borrow(snapshot),mutation.borrow(&payload),g));if matches!(observed(step,heap,g),RetainedCloneStep::Complete(_)){break}}close(&mut cursor)}let mut fenced=Puzzle2dTextInverseCursor::<T>::default();fenced.advance(source.borrow(snapshot),mutation.borrow(&payload),grant(1)).unwrap();let swapped=payload.clone();assert!(fenced.advance(source.borrow(snapshot),mutation.borrow(&swapped),grant(1)).is_err());close(&mut fenced);let mut fenced=Puzzle2dTextInverseCursor::<T>::default();fenced.advance(source.borrow(snapshot),mutation.borrow(&payload),grant(1)).unwrap();let swapped=snapshot.clone();assert!(fenced.advance(source.borrow(&swapped),mutation.borrow(&payload),grant(1)).is_err());close(&mut fenced);assert_eq!(serde_json::to_value(snapshot).unwrap(),original);
}
#[test]
fn history_edit_puzzle2d_optional_text_inverse_clones_only_original_paged_id_and_value_with_exact_cancel(){
 let corpus:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();for row in corpus["cases"].as_array().unwrap(){let mut snapshot=Puzzle2dSnapshot::default();let id=if row["target"].as_bool().unwrap(){"retained"}else{"missing"}.into();let previous=row["before"].as_str().map(PagedUtf8::from);let next=row["next"].as_str().map(PagedUtf8::from);if row["role"]=="nodeIcon"{snapshot.nodes.push(crate::Puzzle2dNode{id:"retained".into(),icon_kind:previous,..Default::default()});snapshot.nodes.push(crate::Puzzle2dNode{id:"retained".into(),icon_kind:Some("second owner".into()),..Default::default()});law(&snapshot,ChangeNodeIcon{id,new_icon_kind:next},&row["expectedInverse"])}else{snapshot.target_regions.push(crate::Puzzle2dTargetRegion{id:"retained".into(),label:previous,..Default::default()});snapshot.target_regions.push(crate::Puzzle2dTargetRegion{id:"retained".into(),label:Some("second owner".into()),..Default::default()});law(&snapshot,EditTargetRegionLabel{id,new_label:next},&row["expectedInverse"])}}
 let text="😀\0甲".repeat(20000);let mut snapshot=Puzzle2dSnapshot::default();snapshot.nodes.push(crate::Puzzle2dNode{id:"retained".into(),icon_kind:Some(text.clone().into()),..Default::default()});law(&snapshot,ChangeNodeIcon{id:"retained".into(),new_icon_kind:None},&serde_json::json!([{"id":"retained","previous":text}]));eprintln!("[DEBUG] optional text inverse fourteen first-owner cases plus160000byte Unicode/NUL clone; constructor0, every actual copy/capacity/release4096, five exact cancellation points and output retirement");
}
